BEGIN;
CREATE TABLE schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_owner(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), user_id text NOT NULL UNIQUE, email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 160), name_en text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(company_id uuid NOT NULL REFERENCES companies(id), user_id text NOT NULL, email text NOT NULL, role text NOT NULL CHECK(role IN ('company_admin','operations','sales','sales_manager','sales_admin','finance_manager','accountant')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(company_id,user_id));
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id), UNIQUE(company_id,name));
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, company_id uuid REFERENCES companies(id), actor_id text NOT NULL, actor_email text NOT NULL, action text NOT NULL, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_company_time ON audit_logs(company_id,created_at DESC);
CREATE INDEX projects_company ON projects(company_id);
CREATE ROLE bunyra_tenant NOLOGIN NOSUPERUSER NOBYPASSRLS;
GRANT USAGE ON SCHEMA public TO bunyra_tenant;
GRANT SELECT ON companies,memberships,projects TO bunyra_tenant;
ALTER TABLE companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE companies FORCE ROW LEVEL SECURITY;
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE projects FORCE ROW LEVEL SECURITY;
CREATE POLICY company_scope ON companies FOR SELECT TO bunyra_tenant USING(id::text = current_setting('app.company_id',true));
CREATE POLICY membership_scope ON memberships FOR SELECT TO bunyra_tenant USING(company_id::text = current_setting('app.company_id',true));
CREATE POLICY project_scope ON projects FOR SELECT TO bunyra_tenant USING(company_id::text = current_setting('app.company_id',true));
GRANT bunyra_tenant TO neondb_owner;
INSERT INTO schema_migrations(version) VALUES('001-foundation');
COMMIT;
